    # large L-like object in the grid, which is the 6 motif, and recolor it 0.
    all_objects = []
    for color in range(10):
        if color == 3:  # uniform background
            continue
        for obj in components(grid, color):
            all_objects.append((color, obj))
    marker = next((obj for color, obj in all_objects if color == 0 and len(obj) >= 8), None)
    if marker is None:
        return out
